
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_revtm_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_revtm", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.654652961702751e+00, -4.561984971143038e+00, -4.432201127566442e+00, -4.252559092531531e+00, -4.008074844815378e+00, -3.683329978296850e+00, -3.266719143442220e+00, -2.757976647365361e+00, -2.177473547892228e+00, -1.568416001823990e+00, -1.009070916403287e+00, -6.979452223543854e-01, -5.995361055140956e-01, -5.078222123873225e-01, -3.666083540392058e-01, -2.263405214923838e-01, -1.198042911198071e-01, -5.402607930226674e-02, -2.012387299576553e-02, -5.340822193374124e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


